	@Test
	void labelLocalNameAndNamespaceStayOnTheNativeRowTier() {
		Extension label = new Extension(pattern("label"));
		label.addElement(new ExtensionElem(new Label(new Var("value")), "result"));

		Extension iriParts = new Extension(pattern("ref"));
		iriParts.addElement(new ExtensionElem(new LocalName(new Var("value")), "local"));
		iriParts.addElement(new ExtensionElem(new Namespace(new Var("value")), "namespace"));

		assertNativeWithoutIsland(new QueryRoot(label));
		assertNativeWithoutIsland(new QueryRoot(iriParts));
	}

